        "cb_s6" to arrayOf("Secuencia definitiva", "Final sequence", "Sequência definitiva", "最终序列"),
        "cb_s6_d" to arrayOf("Así se comporta la barra desde que enciendes el coche: 1 bienvenida → luz fija → parte 2 → parte 3 hasta que te muevas → 4 luz fija en movimiento. Elige qué va en cada parte.", "This is how the bar behaves from when you start the car: 1 welcome → fixed light → part 2 → part 3 until you move → 4 fixed light while moving. Choose what goes in each part.", "Assim a barra se comporta desde que liga o carro: 1 boas-vindas → luz fixa → parte 2 → parte 3 até se mover → 4 luz fixa em movimento. Escolha o que vai em cada parte.", "灯条从启动汽车开始的行为：1 欢迎 → 固定灯光 → 第2阶段 → 第3阶段直到行驶 → 4 行驶时固定灯光。选择每个阶段使用什么。"),
        "cb_q1" to arrayOf("Bienvenida", "Welcome", "Boas-vindas", "欢迎"),
        "cb_q1_d" to arrayOf("Al arrancar. Números = bienvenidas de fábrica; «Mía» = una de tus animaciones.", "At start-up. Numbers = factory welcomes; “Mine” = one of your animations.", "Ao ligar. Números = boas-vindas de fábrica; «Minha» = uma das suas animações.", "启动时。数字=出厂欢迎动画；“我的”=你的动画之一。"),
        "cb_mine" to arrayOf("Mía {0}", "Mine {0}", "Minha {0}", "我的{0}"),
