        "cb_q3" to arrayOf("Después, hasta que te muevas", "Then, until you move", "Depois, até se mover", "之后，直到行驶"),
        "cb_q3_d" to arrayOf("Es la parte que sigue indefinidamente mientras sigas parado. Puede ser el efecto de Ajustes, luz fija o una animación tuya.", "This part continues as long as you stay parked. It can be the Settings effect, fixed light or one of your animations.", "É a parte que continua enquanto estiver parado. Pode ser o efeito dos Ajustes, luz fixa ou uma animação sua.", "只要停车就一直持续的阶段。可以是设置中的效果、固定灯光或你的动画。"),
        "cb_q_set" to arrayOf("Efecto de Ajustes", "Settings effect", "Efeito dos Ajustes", "设置中的效果"),
        "cb_q_fixed" to arrayOf("Luz fija", "Fixed light", "Luz fixa", "固定灯光"),
        "cb_q4" to arrayOf("En movimiento", "While moving", "Em movimento", "行驶中"),
        "cb_q4_d" to arrayOf("Siempre luz fija con el brillo de siempre, o el de tu programación de día y noche si la tienes activada. Esto no cambia. Se ajusta en la pestaña Control.", "Always fixed light at your usual brightness, or your day/night schedule brightness if enabled. This does not change. It is set in the Control tab.", "Sempre luz fixa com o brilho de sempre, ou o da programação dia/noite se estiver ativa. Isto não muda. Ajusta-se na aba Controle.", "始终为固定灯光，使用平时的亮度，若启用了日夜程序则使用其亮度。此项不变，在“控制”页签设置。"),
        "cb_seq_try" to arrayOf("Probar esta secuencia en la barra (sin guardar)", "Try this sequence on the bar (not saved)", "Testar esta sequência na barra (sem guardar)", "在灯条上试用此序列（不保存）"),
        "cb_seq_try_d" to arrayOf("Aplica la secuencia y los tiempos temporalmente. Deja el coche parado para verla. Las animaciones propias deben estar ya en la barra (guárdalas en la sección 7 o pruébalas antes).", "Applies the sequence and timings temporarily. Leave the car parked to see it. Your own animations must already be on the bar (save them in section 7).", "Aplica a sequência e os tempos temporariamente. Deixe o carro parado para ver. As animações próprias já devem estar na barra (guarde-as na seção 7).", "临时应用序列和时间。让汽车保持停车以便观看。自己的动画必须已在灯条中（请在第7节保存）。"),
        "cb_seq_tried" to arrayOf("Secuencia aplicada (temporal).", "Sequence applied (temporary).", "Sequência aplicada (temporária).", "序列已应用（临时）。"),
        "cb_s7" to arrayOf("Guardar en la barra", "Save to the bar", "Guardar na barra", "保存到灯条"),
        "cb_s7_d" to arrayOf("Graba tus animaciones y la secuencia en la memoria de la barra para que se mantengan al apagar el coche.", "Writes your animations and the sequence to the bar memory so they are kept when the car is switched off.", "Grava suas animações e a sequência na memória da barra para que permaneçam ao desligar o carro.", "把动画和序列写入灯条存储，关闭汽车后仍然保留。"),
        "cb_warn" to arrayOf("⚠ CUIDADO: guardar escribe en la memoria permanente de la barra. No lo hagas repetidamente; usa «Probar» para ir ajustando y guarda solo cuando esté definitivo.", "⚠ CAREFUL: saving writes to the bar’s permanent memory. Do not do it repeatedly; use “Try” to fine-tune and save only when final.", "⚠ CUIDADO: guardar escreve na memória permanente da barra. Não faça isso repetidamente; use «Testar» para ajustar e guarde só quando estiver definitivo.", "⚠ 注意：保存会写入灯条的永久存储。不要反复保存；先用“试用”调整，确定后再保存。"),
        "cb_save" to arrayOf("Guardar en la barra", "Save to the bar", "Guardar na barra", "保存到灯条"),
        "cb_save_t" to arrayOf("¡Cuidado!", "Careful!", "Cuidado!", "注意！"),
        "cb_save_m" to arrayOf("Vas a escribir en la memoria de la barra: se grabarán tus animaciones usadas, la secuencia y los ajustes (tiempos y efecto). La memoria aguanta muchas escrituras pero no es infinita.\n\nNo apagues el coche ni te alejes hasta que diga «Guardado y verificado». Si algo sale mal, puedes volver a lo de fábrica con «Restablecer» en Ajustes.", "You are about to write to the bar’s memory: your used animations, the sequence and the settings (timings and effect) will be stored. The memory withstands many writes but is not unlimited.\n\nDo not switch the car off or walk away until it says “Saved and verified”. If anything goes wrong, you can go back to factory with “Reset” in Settings.", "Você vai escrever na memória da barra: serão gravadas as animações usadas, a sequência e os ajustes (tempos e efeito). A memória aguenta muitas gravações, mas não é infinita.\n\nNão desligue o carro nem se afaste até aparecer «Guardado e verificado». Se algo der errado, volte ao padrão com «Restaurar» em Ajustes.", "即将写入灯条存储：会保存用到的动画、序列和设置（时间与效果）。存储可承受多次写入，但并非无限。\n\n在提示“已保存并验证”之前，请勿熄火或离开。如有问题，可在“设置”中点“恢复”回到出厂状态。"),
        "cb_save_chk" to arrayOf("Lo entiendo", "I understand", "Entendi", "我明白"),
        "cb_saving" to arrayOf("Guardando…", "Saving…", "Guardando…", "保存中…"),
